function createBusinessId(name: string) {
  const slug = name
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 35);

  const suffix = Math.random().toString(36).slice(2, 8);
  return `${slug || "comercio"}-${suffix}`;
}

// ------------------------------------------------------
// ENLACES DE DESTINO (cualquier URL http/https)
// ------------------------------------------------------

// Agrega https:// si la persona pegó el enlace sin el protocolo.
function normalizeDestinationUrl(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return "";
  return /^[a-z][a-z0-9+.-]*:/i.test(trimmed) ? trimmed : `https://${trimmed}`;
}

// Única regla: http/https y un dominio con punto. Se acepta cualquier sitio.
function isValidDestinationUrl(value: string) {
  try {
    const url = new URL(value);
    return (
      (url.protocol === "https:" || url.protocol === "http:") &&
      url.hostname.includes(".")
    );
  } catch {
    return false;
  }
}

