// Detecta el tipo de cartel según el dominio del enlace.
function detectLinkKind(value: string): LinkKind {
  try {
    const host = new URL(value).hostname.toLowerCase().replace(/^www\./, "");
    const is = (...domains: string[]) =>
      domains.some((domain) => host === domain || host.endsWith(`.${domain}`));

    if (is("google.com", "g.page", "goo.gl", "share.google", "g.co")) return "google";
    if (is("instagram.com", "instagr.am")) return "instagram";
    if (is("facebook.com", "fb.com", "fb.me", "fb.watch")) return "facebook";
    if (is("wa.me", "whatsapp.com")) return "whatsapp";
    if (is("tiktok.com")) return "tiktok";
    if (is("youtube.com", "youtu.be")) return "youtube";
  } catch {
    // Si la URL no se puede leer, cae en "web".
  }
  return "web";
}

