  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [businessName, setBusinessName] = useState("");
  const [googleReviewUrl, setGoogleReviewUrl] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const [copyMessage, setCopyMessage] = useState("");
  const [promoImageDataUrl, setPromoImageDataUrl] = useState("");
  const [promoError, setPromoError] = useState("");
  const [promoLanguage, setPromoLanguage] = useState<PromoLanguage>("es");
  const [promoLogo, setPromoLogo] = useState<LogoAsset | null>(null);
  const [promoLogoError, setPromoLogoError] = useState("");
  const [isProcessingLogo, setIsProcessingLogo] = useState(false);
  const logoInputRef = useRef<HTMLInputElement | null>(null);
  const [promoKind1, setPromoKind1] = useState<LinkKind | "auto">("auto");
  const [promoUrl2, setPromoUrl2] = useState("");
  const [promoKind2, setPromoKind2] = useState<LinkKind | "auto">("auto");
  const [isDeletingBusiness, setIsDeletingBusiness] = useState(false);
  const [isEditingBusiness, setIsEditingBusiness] = useState(false);
  const [editBusinessName, setEditBusinessName] = useState("");
  const [editGoogleReviewUrl, setEditGoogleReviewUrl] = useState("");
  const [managementError, setManagementError] = useState("");
  const [managementSuccess, setManagementSuccess] = useState("");

  // ====================================================
  // PÁGINA PÚBLICA
  // ====================================================

  const [publicBusinessId, setPublicBusinessId] = useState<string | null>(
    null
  );
  const [publicBusiness, setPublicBusiness] = useState<Business | null>(null);
  const [publicLoading, setPublicLoading] = useState(false);
  const [publicError, setPublicError] = useState("");
  const isPublicPage = publicBusinessId !== null;

  // ====================================================
  // COMERCIO SELECCIONADO
  // ====================================================

  const selectedBusiness =
    businesses.find((business) => business.id === selectedId) ?? null;

  // ====================================================
  // FILTRO DE COMERCIOS
  // ====================================================

  const filteredBusinesses = useMemo(() => {
    const normalizedSearch = searchTerm.trim().toLowerCase();

    if (!normalizedSearch) {
      return businesses;
    }

    return businesses.filter((business) =>
      business.name.toLowerCase().includes(normalizedSearch)
    );
  }, [businesses, searchTerm]);

  // ====================================================
  // PAGINACIÓN
  // ====================================================

  const totalPages = Math.max(
    1,
    Math.ceil(filteredBusinesses.length / BUSINESSES_PER_PAGE)
  );

  const paginatedBusinesses = filteredBusinesses.slice(
    (currentPage - 1) * BUSINESSES_PER_PAGE,
    currentPage * BUSINESSES_PER_PAGE
  );

  // ====================================================
  // URL PÚBLICA
  // ====================================================

  const landingUrl =
    selectedBusiness && typeof window !== "undefined"
      ? `${window.location.origin}/?b=${encodeURIComponent(
          selectedBusiness.id
        )}`
      : "";

  // El QR codifica directamente el enlace de reseñas de Google del negocio
  // (no depende de la web ni de la base de datos de ReseñaTap).
  const qrTargetUrl = selectedBusiness?.google_review_url ?? "";

  // Segundo destino opcional del cartel (hasta 2 QR por cartel).
  const secondUrlNormalized = normalizeDestinationUrl(promoUrl2);
  const secondUrlIsValid =
    secondUrlNormalized !== "" && isValidDestinationUrl(secondUrlNormalized);
  const detectedKind1: LinkKind = qrTargetUrl ? detectLinkKind(qrTargetUrl) : "web";
  const detectedKind2: LinkKind = secondUrlIsValid
    ? detectLinkKind(secondUrlNormalized)
    : "web";
  const kindLabel = (kind: LinkKind) =>
    LINK_KIND_OPTIONS.find((option) => option.value === kind)?.label ?? kind;

  // ====================================================
  // CARGA INICIAL
  // ====================================================

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const businessId = params.get("b");

    if (businessId) {
      setPublicBusinessId(businessId);
      setPublicLoading(true);

      const loadPublicBusiness = async () => {
        const { data, error } = await supabase
          .from("businesses")
          .select("*")
          .eq("id", businessId)
          .single();

        if (error || !data) {
          setPublicError(
            "No encontramos este comercio o el enlace ya no está activo."
          );
          setPublicBusiness(null);
        } else {
          setPublicBusiness(data as Business);
        }

        setPublicLoading(false);
      };

      void loadPublicBusiness();
      return;
    }

    let isMounted = true;

    const checkSession = async () => {
      const { data, error } = await supabase.auth.getSession();
      const user = data.session?.user;
      const isAdmin = !error && !!user?.id && ADMIN_USER_IDS.includes(user.id);

      if (isAdmin) {
        if (isMounted) {
          setIsLoggedIn(true);
          setIsCheckingLogin(false);
          void loadBusinesses();
        }
        return;
      }

      // Una sesión de otro usuario no debe abrir el panel de administración.
      if (user) {
        await supabase.auth.signOut();
      }

      if (isMounted) {
        setIsLoggedIn(false);
        setIsCheckingLogin(false);
        setIsLoading(false);
      }
    };

    void checkSession();

    const { data: authListener } = supabase.auth.onAuthStateChange(
      (_event, session) => {
        const user = session?.user;
        const isAdmin = !!user?.id && ADMIN_USER_IDS.includes(user.id);

        if (isAdmin) {
          setIsLoggedIn(true);
          void loadBusinesses();
        } else {
          setIsLoggedIn(false);
          setBusinesses([]);
          setIsLoading(false);
        }
        setIsCheckingLogin(false);
      }
    );

    return () => {
      isMounted = false;
      authListener.subscription.unsubscribe();
    };
  }, []);

  // ====================================================
  // CARGAR COMERCIOS
  // ====================================================

  async function loadBusinesses() {
    setIsLoading(true);
    setErrorMessage("");

    const { data, error } = await supabase
      .from("businesses")
      .select("*")
      .order("created_at", { ascending: false });

    if (error) {
      setErrorMessage(
        "No pudimos cargar los comercios. Probá nuevamente."
      );
      setBusinesses([]);
    } else {
      setBusinesses((data ?? []) as Business[]);
    }

    setIsLoading(false);
  }

  // ====================================================
  // LOGIN
  // ====================================================

  async function handleLogin(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setLoginError("");
    setIsLoggingIn(true);

    const { data, error } = await supabase.auth.signInWithPassword({
      email: loginEmail.trim(),
      password: loginPassword,
    });

    if (error || !data.user) {
      setLoginError("Correo o contraseña incorrectos.");
      setIsLoggingIn(false);
      return;
    }

    if (!ADMIN_USER_IDS.includes(data.user.id)) {
      await supabase.auth.signOut();
      setLoginError("Esta cuenta no tiene permisos de administrador.");
      setIsLoggingIn(false);
      return;
    }

    setIsLoggedIn(true);
    setLoginEmail("");
    setLoginPassword("");
    setShowPassword(false);
    setIsLoggingIn(false);
  }

  // ====================================================
  // LOGOUT
  // ====================================================

  async function handleLogout() {
    await supabase.auth.signOut();
    setIsLoggedIn(false);
    setSelectedId(null);
    setBusinesses([]);
    setBusinessName("");
    setGoogleReviewUrl("");
    setSearchTerm("");
    setCurrentPage(1);
    setErrorMessage("");
    setSuccessMessage("");
  }

  // ====================================================
  // REGISTRAR COMERCIO
  // ====================================================

  async function handleRegisterBusiness(
    event: FormEvent<HTMLFormElement>
  ) {
    event.preventDefault();

    setErrorMessage("");
    setSuccessMessage("");

    const cleanName = businessName.trim();
    const cleanUrl = normalizeDestinationUrl(googleReviewUrl);

    if (!cleanName) {
      setErrorMessage("Ingresá el nombre del comercio.");
      return;
    }

    if (!isValidDestinationUrl(cleanUrl)) {
      setErrorMessage(
        "Ingresá un enlace válido (por ejemplo https://instagram.com/tu_negocio)."
      );
      return;
    }

    setIsSaving(true);

    const newBusiness = {
      id: createBusinessId(cleanName),
      name: cleanName,
      google_review_url: cleanUrl,
    };

    const { data, error } = await supabase
      .from("businesses")
      .insert(newBusiness)
      .select("*")
      .single();

    if (error || !data) {
      setErrorMessage(
        "No pudimos registrar el comercio. Revisá los datos e intentá otra vez."
      );
      setIsSaving(false);
      return;
    }

    const createdBusiness = data as Business;

    setBusinesses((previous) => [
      createdBusiness,
      ...previous,
    ]);

    setSelectedId(createdBusiness.id);
    setBusinessName("");
    setGoogleReviewUrl("");
    setSearchTerm("");
    setCurrentPage(1);

    setSuccessMessage(
      "¡Comercio registrado! Ya podés usar su QR y enlace."
    );

    setIsSaving(false);
  }

  // ====================================================
  // COPIAR ENLACE PÚBLICO
  // ====================================================

  async function copyLandingUrl() {
    if (!landingUrl) return;

    try {
      await navigator.clipboard.writeText(landingUrl);
      setCopyMessage("¡Enlace copiado!");
    } catch {
      setCopyMessage(
        "No se pudo copiar automáticamente. Seleccioná y copiá el enlace manualmente."
      );
    }
  }

  // ====================================================
  // DESCARGAR QR
  // ====================================================

  function downloadQrCode() {
    const svg = document.getElementById("resenatap-qr");

    if (!svg || !selectedBusiness) {
      return;
    }

    const serializer = new XMLSerializer();
    const svgText = serializer.serializeToString(svg);

    const blob = new Blob([svgText], {
      type: "image/svg+xml;charset=utf-8",
    });

    const downloadUrl = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = downloadUrl;
    link.download = `resenatap-${selectedBusiness.id}.svg`;

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    URL.revokeObjectURL(downloadUrl);
  }

  // ====================================================
  // GENERAR IMAGEN PROMOCIONAL (SIN GUARDAR EN SUPABASE)
  // ====================================================

  async function createPromoImage(
    language: PromoLanguage,
    kind1: LinkKind,
    kind2: LinkKind | null,
    logo: LogoAsset | null
  ): Promise<string> {
    if (!selectedBusiness) {
      throw new Error("Seleccioná un comercio para generar su imagen.");
    }

    const dual = kind2 !== null;
    const objectUrls: string[] = [];

    try {
      // ------------------------------------------------
      // Carga de QR (1 o 2) y de logos opcionales
      // ------------------------------------------------
      const loadQr = async (elementId: string) => {
        const element = document.getElementById(elementId);
        if (!(element instanceof SVGElement)) {
          throw new Error("No encontramos el QR de este comercio. Volvé a abrirlo e intentá nuevamente.");
        }
        // qrcode.react agrega 4 módulos de margen blanco por lado dentro del SVG.
        // Lo recortamos al dibujar: la tarjeta blanca ya aporta la zona de silencio.
        const viewBox = element.getAttribute("viewBox");
        const cells = viewBox ? Number(viewBox.split(/[\s,]+/)[2]) : 0;
        const crop = Number.isFinite(cells) && cells > 8 ? 4 / cells : 0;
        const svgText = new XMLSerializer().serializeToString(element);
        const svgBlob = new Blob([svgText], { type: "image/svg+xml;charset=utf-8" });
        const svgUrl = URL.createObjectURL(svgBlob);
        objectUrls.push(svgUrl);
        const image = new Image();
        await new Promise<void>((resolve, reject) => {
          image.onload = () => resolve();
          image.onerror = () => reject(new Error("No se pudo preparar el QR para la imagen."));
          image.src = svgUrl;
        });
        return { image, crop };
      };

      const loadLogo = (kind: LinkKind) =>
        new Promise<HTMLImageElement | null>((resolve) => {
          const source = PROMO_LOGO_DATA[kind];
          if (!source) {
            resolve(null);
            return;
          }
          const image = new Image();
          image.onload = () =>
            resolve(image.naturalWidth > 0 && image.naturalHeight > 0 ? image : null);
          image.onerror = () => resolve(null);
          image.src = source;
        });

      const qrAsset1 = await loadQr("resenatap-qr");
      const qrAsset2 = dual ? await loadQr("resenatap-qr-2") : null;
      const logos: Partial<Record<LinkKind, HTMLImageElement | null>> = {};
      for (const kind of dual ? [kind1, kind2 as LinkKind] : [kind1]) {
        if (!(kind in logos)) logos[kind] = await loadLogo(kind);
      }

      // Imagen del comercio (opcional): si no hay, el cartel sale exactamente como siempre.
      let logoImage: HTMLImageElement | null = null;
      let placement: LogoPlacement | null = null;
      if (logo) {
        logoImage = await new Promise<HTMLImageElement>((resolve, reject) => {
          const image = new Image();
          image.onload = () => resolve(image);
          image.onerror = () =>
            reject(new Error("No se pudo usar la imagen del comercio. Quitala y probá con otra."));
          image.src = logo.dataUrl;
        });
        placement = chooseLogoPlacement(logo);
      }

      // Cartel vertical 2:3. No se guarda nada en Supabase.
      const W = 1024;
      const H = 1536;
      const canvas = document.createElement("canvas");
      canvas.width = W;
      canvas.height = H;
      const context = canvas.getContext("2d");
      if (!context) throw new Error("El navegador no pudo crear la imagen.");
      const g: CanvasRenderingContext2D = context;

      // ------------------------------------------------
      // Colores y textos
      // ------------------------------------------------
      const navy = "#0b2a4a";
      const blue = "#1673e6";
      const grey = "#5b6b80";
      const gold = "#fbbc04";
      const red = "#ea4335";
      const green = "#34a853";
      const gBlue = "#4285f4";
      const font = "Arial, Helvetica, sans-serif";
      const cx = W / 2;

      const both = language === "both";
      const pl: PromoLang = language === "en" ? "en" : "es";
      const sl: PromoLang | null = both ? "en" : null;

      const kinds: LinkKind[] = dual ? [kind1, kind2 as LinkKind] : [kind1];
      const hasGoogle = kinds.includes("google");
      const common = PROMO_COMMON[pl];
      const commonSec = sl ? PROMO_COMMON[sl] : null;

      const headlineText = dual
        ? hasGoogle
          ? KIND_TEXTS.google[pl].headline
          : common.headlineGeneral
        : KIND_TEXTS[kind1][pl].headline;
      const headlineSec = sl
        ? dual
          ? hasGoogle
            ? KIND_TEXTS.google[sl].headline
            : (commonSec as NonNullable<typeof commonSec>).headlineGeneral
          : KIND_TEXTS[kind1][sl].headline
        : null;
      const showStars = hasGoogle;
      const taglineText = hasGoogle ? common.taglineReview : common.taglineGeneral;
      const taglineSec = commonSec
        ? hasGoogle
          ? commonSec.taglineReview
          : commonSec.taglineGeneral
        : null;
      const sloganText = hasGoogle ? common.sloganReview : common.sloganGeneral;
      const sloganSec = commonSec
        ? hasGoogle
          ? commonSec.sloganReview
          : commonSec.sloganGeneral
        : null;

      // ------------------------------------------------
      // Utilidades de dibujo
      // ------------------------------------------------
      const setFont = (size: number, weight = "bold", style = "", family = font) => {
        g.font = `${style} ${weight} ${size}px ${family}`.trim();
      };

      const fitSize = (text: string, maxWidth: number, startSize: number, weight = "bold", style = "", family = font) => {
        let size = startSize;
        while (size > 10) {
          setFont(size, weight, style, family);
          if (g.measureText(text).width <= maxWidth) break;
          size -= 1;
        }
        return size;
      };

      const circle = (x: number, y: number, r: number, color: string) => {
        g.beginPath();
        g.arc(x, y, r, 0, Math.PI * 2);
        g.fillStyle = color;
        g.fill();
      };

      const rr = (x: number, y: number, w: number, h: number, r: number, fill: string, stroke?: string, lineWidth = 1) => {
        g.beginPath();
        g.roundRect(x, y, w, h, r);
        g.fillStyle = fill;
        g.fill();
        if (stroke) {
          g.lineWidth = lineWidth;
          g.strokeStyle = stroke;
          g.stroke();
        }
      };

      const star = (x: number, y: number, outer: number, inner: number, color: string) => {
        g.beginPath();
        for (let i = 0; i < 10; i++) {
          const radius = i % 2 === 0 ? outer : inner;
          const angle = -Math.PI / 2 + (i * Math.PI) / 5;
          const px = x + Math.cos(angle) * radius;
          const py = y + Math.sin(angle) * radius;
          if (i === 0) g.moveTo(px, py);
          else g.lineTo(px, py);
        }
        g.closePath();
        g.fillStyle = color;
        g.fill();
      };

      const googleG = (x: number, y: number, r: number) => {
        const rad = (deg: number) => (deg * Math.PI) / 180;
        const thickness = r * 0.38;
        const arcRadius = r - thickness / 2;
        g.save();
        g.lineWidth = thickness;
        g.lineCap = "butt";
        const segments: Array<[number, number, string]> = [
          [205, 318, red],
          [135, 205, "#fbbc05"],
          [45, 135, green],
          [-15, 45, gBlue],
        ];
        for (const [from, to, color] of segments) {
          g.beginPath();
          g.arc(x, y, arcRadius, rad(from), rad(to));
          g.strokeStyle = color;
          g.stroke();
        }
        g.fillStyle = gBlue;
        g.fillRect(x, y - thickness / 2, r * 0.95, thickness);
        g.restore();
      };

      const nfcWaves = (x: number, y: number, scale: number) => {
        g.save();
        g.strokeStyle = navy;
        g.lineWidth = 9 * scale;
        g.lineCap = "round";
        for (let i = 0; i < 3; i++) {
          g.beginPath();
          g.arc(x - 14 * scale, y, (18 + i * 17) * scale, -0.9, 0.9);
          g.stroke();
        }
        g.restore();
      };

      // Marca de plataforma: "G" de Google, logo (si existe el archivo) o etiqueta de texto.
      const drawMark = (kind: LinkKind, mx: number, my: number, h: number, withName: boolean) => {
        const name = KIND_TEXTS[kind][pl].platform;
        const logo = logos[kind] ?? null;

        if (kind !== "google" && !logo) {
          const fontSize = Math.round(h * 0.5);
          setFont(fontSize, "bold");
          const pillW = g.measureText(name).width + h * 0.9;
          rr(mx - pillW / 2, my - h / 2, pillW, h, h / 2, PLATFORM_COLORS[kind]);
          g.textAlign = "center";
          g.fillStyle = "#ffffff";
          g.fillText(name, mx, my + fontSize * 0.35);
          return;
        }

        const iconW = logo ? Math.min(h * (logo.width / logo.height), h * 2) : h;
        let nameW = 0;
        const nameSize = Math.round(h * 0.62);
        const gap = 14;
        if (withName) {
          setFont(nameSize, "bold");
          nameW = g.measureText(name).width;
        }
        const total = iconW + (withName ? gap + nameW : 0);
        const startX = mx - total / 2;

        if (logo) g.drawImage(logo, startX, my - h / 2, iconW, h);
        else googleG(startX + h / 2, my, h / 2);

        if (withName) {
          setFont(nameSize, "bold");
          g.textAlign = "left";
          g.fillStyle = navy;
          g.fillText(name, startX + iconW + gap, my + nameSize * 0.35);
        }
      };

      // ------------------------------------------------
      // Fondo y adornos de esquina
      // ------------------------------------------------
      g.fillStyle = "#ffffff";
      g.fillRect(0, 0, W, H);

      // Esquina superior izquierda (amarillo + azul).
      circle(22, 22, 175, gold);
      circle(-6, -6, 140, gBlue);

      // Destellos de colores arriba a la derecha.
      const sparkles: Array<[number, string]> = [
        [215, gBlue],
        [180, red],
        [145, gold],
        [110, green],
      ];
      g.save();
      g.lineWidth = 12;
      g.lineCap = "round";
      for (const [deg, color] of sparkles) {
        const a = (deg * Math.PI) / 180;
        g.beginPath();
        g.moveTo(950 + Math.cos(a) * 22, 115 + Math.sin(a) * 22);
        g.lineTo(950 + Math.cos(a) * 60, 115 + Math.sin(a) * 60);
        g.strokeStyle = color;
        g.stroke();
      }
      g.restore();

      // Esquina inferior derecha (círculos de colores).
      g.save();
      g.beginPath();
      g.rect(0, 0, W, H);
      g.clip();
      circle(850, 1565, 92, red);
      circle(985, 1455, 108, gold);
      circle(1042, 1345, 62, gBlue);
      circle(992, 1585, 200, green);
      g.restore();

      // ------------------------------------------------
      // Marca ReseñaTap: chica y discreta, arriba (NO es la protagonista).
      // Si el comercio sube su logo o imagen, la marca ReseñaTap se quita y queda solo lo del cliente.
      // ------------------------------------------------
      if (!logoImage) {
        setFont(46, "bold");
        const reseñaW = g.measureText("Reseña").width;
        const tapW = g.measureText("Tap").width;
        const logoW = reseñaW + tapW;
        const miniIconW = 56;
        const miniGap = 14;
        const brandGroupW = miniIconW + miniGap + logoW;
        const brandX = cx - brandGroupW / 2;
        const brandBase = 92;

        g.save();
        g.translate(brandX, 32);
        g.rotate(-0.08);
        g.scale(0.42, 0.42);
        g.shadowColor = "rgba(9,43,82,0.18)";
        g.shadowBlur = 14;
        g.shadowOffsetY = 6;
        rr(0, 0, 128, 184, 24, navy);
        g.shadowColor = "transparent";
        rr(9, 11, 110, 162, 17, "#ffffff");
        rr(44, 4, 40, 8, 4, navy);
        star(64, 96, 34, 15, gold);
        g.restore();

        g.textAlign = "left";
        setFont(46, "bold");
        g.fillStyle = navy;
        g.fillText("Reseña", brandX + miniIconW + miniGap, brandBase);
        g.fillStyle = blue;
        g.fillText("Tap", brandX + miniIconW + miniGap + reseñaW, brandBase);

        g.textAlign = "center";
        g.fillStyle = grey;
        setFont(20, "normal");
        g.fillText(taglineText, cx, brandBase + 36);
        if (taglineSec) {
          setFont(17, "normal");
          g.fillText(taglineSec, cx, brandBase + 61);
        }
      }

      // ------------------------------------------------
      // Medimos el nombre del comercio (protagonista) para armar el layout
      // ------------------------------------------------
      const heroMaxW = 880;
      const bizName = selectedBusiness.name.trim().replace(/\s+/g, " ").toUpperCase();
      const words = bizName.split(" ");
      let heroLines: string[] = [bizName];
      let heroSize = fitSize(bizName, heroMaxW, 116);

      if (heroSize < 84 && words.length > 1) {
        // Nombre largo: lo partimos en dos líneas equilibradas y más grandes.
        let bestSplit = 1;
        let bestWidth = Infinity;
        setFont(100, "bold");
        for (let i = 1; i < words.length; i++) {
          const w = Math.max(
            g.measureText(words.slice(0, i).join(" ")).width,
            g.measureText(words.slice(i).join(" ")).width
          );
          if (w < bestWidth) {
            bestWidth = w;
            bestSplit = i;
          }
        }
        const twoLines = [words.slice(0, bestSplit).join(" "), words.slice(bestSplit).join(" ")];
        const twoSize = Math.min(
          fitSize(twoLines[0], heroMaxW, 108),
          fitSize(twoLines[1], heroMaxW, 108)
        );
        if (twoSize > heroSize) {
          heroLines = twoLines;
          heroSize = twoSize;
        }
      }

      const heroLineH = Math.round(heroSize * 1.06);
      const headlineSize = fitSize(headlineText, 820, both ? 50 : 58);

      // Alturas base (sin holgura) para repartir el espacio sobrante si el nombre es corto.
      const heroTop0 = 196;
      const heroEnd0 = heroTop0 + Math.round(heroSize * 0.85) + (heroLines.length - 1) * heroLineH;
      const barY0 = heroEnd0 + 34;
      const headY0 = barY0 + 20 + headlineSize + 18;
      const headEnd0 = headlineSec ? headY0 + 50 : headY0;
      const starsY0 = headEnd0 + 62;
      const afterHead0 = showStars ? starsY0 + 34 : headEnd0 + 12;
      const ctaY0 = afterHead0 + 50;
      const gEnd0 = dual ? afterHead0 : ctaY0 + (headlineSec ? 44 : 18);
      const cardGapBase = dual ? 96 : 28;
      const cardY0 = gEnd0 + cardGapBase;
      const slack = Math.max(0, 640 - cardY0);

      const heroTop = heroTop0 + slack * 0.3;
      const barY = barY0 + slack * 0.4;
      const headY = headY0 + slack * 0.55;
      const headEnd = headEnd0 + slack * 0.55;
      const starsY = starsY0 + slack * 0.7;
      const ctaY = ctaY0 + slack * 0.85;
      const gEnd = gEnd0 + slack * 0.85;
      const cardGap = cardGapBase + slack * 0.15;

      // ------------------------------------------------
      // Imagen / logo del comercio, respetando proporciones (sin estirar ni recortar logos)
      // ------------------------------------------------
      if (logo && logoImage && placement) {
        const img = logoImage;
        const iw = img.naturalWidth;
        const ih = img.naturalHeight;
        const opaque = !logo.hasAlpha;
        g.imageSmoothingQuality = "high";

        const topCenterY = 108; // centro de la zona donde antes estaba la marca ReseñaTap

        if (placement === "medallion") {
          // Foto representativa: medallón circular con borde blanco.
          const mx = cx;
          const my = topCenterY + 4;
          const radius = 75;
          g.save();
          g.shadowColor = "rgba(9,43,82,0.22)";
          g.shadowBlur = 22;
          g.shadowOffsetY = 8;
          circle(mx, my, radius, "#ffffff");
          g.restore();
          g.save();
          g.beginPath();
          g.arc(mx, my, radius - 8, 0, Math.PI * 2);
          g.clip();
          const coverScale = Math.max(((radius - 8) * 2) / iw, ((radius - 8) * 2) / ih);
          g.drawImage(img, mx - (iw * coverScale) / 2, my - (ih * coverScale) / 2, iw * coverScale, ih * coverScale);
          g.restore();
        } else {
          // Logo: compacto o apaisado/alto, centrado arriba y siempre "contain".
          const boxW = placement === "compact" ? 150 : 560;
          const boxH = placement === "compact" ? 150 : 130;
          const centerX = cx;
          const centerY = topCenterY;
          const pad = opaque ? 12 : 0;
          const fit = Math.min((boxW - pad * 2) / iw, (boxH - pad * 2) / ih);
          const dw = iw * fit;
          const dh = ih * fit;
          if (opaque) {
            // Logo con fondo propio (JPG, etc.): tarjeta blanca limpia detrás.
            g.save();
            g.shadowColor = "rgba(9,43,82,0.16)";
            g.shadowBlur = 16;
            g.shadowOffsetY = 6;
            rr(centerX - dw / 2 - pad, centerY - dh / 2 - pad, dw + pad * 2, dh + pad * 2, 22, "#ffffff", "#e6edf5", 2);
            g.restore();
            g.save();
            g.beginPath();
            g.roundRect(centerX - dw / 2, centerY - dh / 2, dw, dh, 12);
            g.clip();
            g.drawImage(img, centerX - dw / 2, centerY - dh / 2, dw, dh);
            g.restore();
          } else {
            // Logo con transparencia: se conserva tal cual sobre el cartel.
            g.drawImage(img, centerX - dw / 2, centerY - dh / 2, dw, dh);
          }
        }
      }

      // ------------------------------------------------
      // PROTAGONISTA: nombre del comercio, grande y en negrita
      // ------------------------------------------------
      g.textAlign = "center";
      g.fillStyle = navy;
      setFont(heroSize, "bold");
      heroLines.forEach((line, i) => {
        g.fillText(line, cx, heroTop + Math.round(heroSize * 0.85) + i * heroLineH);
      });

      // Barra de acento con los 4 colores de Google bajo el nombre.
      {
        const segW = 54;
        const barH = 10;
        const colors = [gBlue, red, gold, green];
        const startX = cx - (segW * 4 + 6 * 3) / 2;
        colors.forEach((color, i) => {
          rr(startX + i * (segW + 6), barY - barH / 2, segW, barH, 5, color);
        });
      }

      // ------------------------------------------------
      // Titular, estrellas (solo reseñas) y línea de acción
      // ------------------------------------------------
      g.textAlign = "center";
      g.fillStyle = blue;
      setFont(headlineSize, "bold");
      g.fillText(headlineText, cx, headY);
      if (headlineSec) {
        const secSize = fitSize(headlineSec, 760, 34);
        setFont(secSize, "bold");
        g.fillStyle = grey;
        g.fillText(headlineSec, cx, headEnd);
      }

      if (showStars) {
        for (let i = 0; i < 5; i++) star(cx + (i - 2) * 76, starsY, 33, 14.5, gold);
      }

      if (!dual) {
        // Una sola acción: ícono (Google o logo si existe) + texto.
        const ctaText = KIND_TEXTS[kind1][pl].cta;
        const logo1 = logos[kind1] ?? null;
        const hasIcon = kind1 === "google" || !!logo1;
        const iconH = 54;
        const iconW = logo1 ? Math.min(iconH * (logo1.width / logo1.height), iconH * 2) : iconH;
        const textMax = hasIcon ? 820 - iconW - 18 : 820;
        const ctaSize = fitSize(ctaText, textMax, 36);
        setFont(ctaSize, "bold");
        const ctaW = g.measureText(ctaText).width;
        const total = hasIcon ? iconW + 18 + ctaW : ctaW;
        const startX = cx - total / 2;
        if (hasIcon) {
          if (logo1) g.drawImage(logo1, startX, ctaY - 12 - iconH / 2, iconW, iconH);
          else googleG(startX + iconH / 2, ctaY - 12, iconH / 2);
        }
        g.textAlign = "left";
        g.fillStyle = navy;
        g.fillText(ctaText, startX + (hasIcon ? iconW + 18 : 0), ctaY);
        if (sl) {
          const secText = KIND_TEXTS[kind1][sl].cta;
          const secSize = fitSize(secText, 820, 24, "normal");
          setFont(secSize, "normal");
          g.textAlign = "center";
          g.fillStyle = grey;
          g.fillText(secText, cx, ctaY + 38);
        }
      }

      // ------------------------------------------------
      // Tarjeta(s) con el/los QR real(es) del comercio
      // ------------------------------------------------
      const drawQrCard = (
        x: number,
        y: number,
        size: number,
        qr: { image: HTMLImageElement; crop: number }
      ) => {
        g.save();
        g.shadowColor = "rgba(9,43,82,0.18)";
        g.shadowBlur = 30;
        g.shadowOffsetY = 10;
        rr(x, y, size, size, 34, "#ffffff", "#e6edf5", 2);
        g.restore();
        const pad = Math.round(size * 0.06);
        const natural = qr.image.naturalWidth || 220;
        const cut = natural * qr.crop;
        g.imageSmoothingEnabled = false;
        g.drawImage(
          qr.image,
          cut,
          cut,
          natural - cut * 2,
          natural - cut * 2,
          x + pad,
          y + pad,
          size - pad * 2,
          size - pad * 2
        );
        g.imageSmoothingEnabled = true;
      };

      const cardY = gEnd + cardGap;
      let cardBottom: number;

      if (!dual) {
        // El QR es protagonista: lo más grande posible sin pisar NFC, celular ni frase final.
        const bottomNeeded = both ? 410 : 375;
        const cardSize = Math.max(340, Math.min(both ? 440 : 480, H - bottomNeeded - cardY));
        drawQrCard(cx - cardSize / 2, cardY, cardSize, qrAsset1);
        cardBottom = cardY + cardSize;

        // NFC (izquierda) y teléfono (derecha).
        const nfcX = 320;
        const nfcY = cardBottom + 78;
        nfcWaves(nfcX, nfcY, 0.95);
        g.textAlign = "center";
        g.fillStyle = grey;
        setFont(27, "normal");
        g.fillText(common.nfc[0], nfcX, nfcY + 66);
        g.fillText(common.nfc[1], nfcX, nfcY + 98);
        if (commonSec) {
          setFont(21, "normal");
          g.fillStyle = "#7d8da3";
          g.fillText(commonSec.nfc[0], nfcX, nfcY + 136);
          g.fillText(commonSec.nfc[1], nfcX, nfcY + 162);
        }

        const phoneScale = both ? 0.78 : 0.92;
        g.save();
        g.translate(745, cardBottom + 45 + 140 * phoneScale);
        g.rotate(0.2);
        g.scale(phoneScale, phoneScale);
        g.save();
        g.shadowColor = "rgba(9,43,82,0.28)";
        g.shadowBlur = 22;
        g.shadowOffsetY = 10;
        rr(-72, -142, 144, 284, 28, navy);
        g.restore();
        rr(-63, -133, 126, 266, 21, "#ffffff");
        rr(-22, -128, 44, 8, 4, navy);
        drawMark(kind1, 0, kind1 === "google" ? -78 : -86, kind1 === "google" ? 36 : 30, false);
        if (kind1 === "google") {
          for (let i = 0; i < 5; i++) star(-36 + i * 18, -38, 8.5, 3.8, gold);
        }
        rr(-46, -10, 92, 30, 15, blue);
        g.textAlign = "center";
        g.fillStyle = "#ffffff";
        const buttonText = KIND_TEXTS[kind1][pl].button;
        const buttonSize = fitSize(buttonText, 80, 12);
        setFont(buttonSize, "bold");
        g.fillText(buttonText, 0, 10);
        rr(-46, 42, 92, 8, 4, "#e6edf5");
        rr(-46, 62, 70, 8, 4, "#e6edf5");
        rr(-46, 82, 82, 8, 4, "#e6edf5");
        g.restore();
      } else {
        // Dos destinos: dos QR lado a lado, cada uno con su etiqueta.
        const cardSize = 456;
        const gapCards = 36;
        const x1 = cx - gapCards / 2 - cardSize;
        const x2 = cx + gapCards / 2;
        const pairs: Array<[number, LinkKind, { image: HTMLImageElement; crop: number }]> = [
          [x1, kind1, qrAsset1],
          [x2, kind2 as LinkKind, qrAsset2 as { image: HTMLImageElement; crop: number }],
        ];
        for (const [x, kind, qr] of pairs) {
          const centerX = x + cardSize / 2;
          drawMark(kind, centerX, cardY - 48, 46, true);
          drawQrCard(x, cardY, cardSize, qr);

          const shortText = KIND_TEXTS[kind][pl].short;
          const shortSize = fitSize(shortText, cardSize - 20, 34);
          setFont(shortSize, "bold");
          g.textAlign = "center";
          g.fillStyle = navy;
          g.fillText(shortText, centerX, cardY + cardSize + 56);
          if (sl) {
            const secText = KIND_TEXTS[kind][sl].short;
            const secSize = fitSize(secText, cardSize - 20, 24, "normal");
            setFont(secSize, "normal");
            g.fillStyle = grey;
            g.fillText(secText, centerX, cardY + cardSize + 90);
          }
        }
        cardBottom = cardY + cardSize;
      }

      // ------------------------------------------------
      // Frase final con subrayado
      // ------------------------------------------------
      const sloganX = dual ? 440 : 395;
      const sloganY = both ? H - 120 : H - 100;
      const sloganSize = fitSize(sloganText, 520, 40, "bold", "italic", "Georgia, serif");
      setFont(sloganSize, "bold", "italic", "Georgia, serif");
      g.textAlign = "center";
      g.fillStyle = navy;
      g.fillText(sloganText, sloganX, sloganY);
      const sloganW = g.measureText(sloganText).width;
      g.strokeStyle = blue;
      g.lineWidth = 5;
      g.lineCap = "round";
      g.beginPath();
      g.moveTo(sloganX - sloganW / 2, sloganY + 22);
      g.quadraticCurveTo(sloganX, sloganY + 4, sloganX + sloganW / 2, sloganY + 20);
      g.stroke();
      if (sloganSec) {
        const enSloganSize = fitSize(sloganSec, 480, 30, "normal", "italic", "Georgia, serif");
        setFont(enSloganSize, "normal", "italic", "Georgia, serif");
        g.fillStyle = blue;
        g.fillText(sloganSec, sloganX, sloganY + 54);
      }

      void cardBottom;
      return canvas.toDataURL("image/png");
    } finally {
      for (const url of objectUrls) URL.revokeObjectURL(url);
    }
  }

  async function handleGeneratePromoImage(
    language: PromoLanguage = promoLanguage,
    logo: LogoAsset | null = promoLogo
  ) {
    setPromoError("");
    setPromoImageDataUrl("");

    if (promoUrl2.trim() && !secondUrlIsValid) {
      setPromoError(
        "El segundo enlace no es válido. Pegá una dirección web completa (por ejemplo https://wa.me/549...)."
      );
      return;
    }

    const kind1 = promoKind1 === "auto" ? detectedKind1 : promoKind1;
    const kind2: LinkKind | null = secondUrlIsValid
      ? promoKind2 === "auto"
        ? detectedKind2
        : promoKind2
      : null;

    try {
      const imageDataUrl = await createPromoImage(language, kind1, kind2, logo);
      setPromoImageDataUrl(imageDataUrl);
    } catch (error) {
      setPromoError(error instanceof Error ? error.message : "No se pudo generar la imagen.");
    }
  }

  // Imagen o logo del comercio: se valida, se convierte si hace falta y se mantiene
  // seleccionada hasta que se quite o se cambie de comercio.
  async function handleLogoSelected(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = ""; // permite volver a elegir el mismo archivo
    if (!file) return;

    setPromoLogoError("");
    setIsProcessingLogo(true);
    try {
      const asset = await processLogoFile(file);
      setPromoLogo(asset);
      // Si ya había un cartel generado, se actualiza con la nueva imagen.
      if (promoImageDataUrl) await handleGeneratePromoImage(promoLanguage, asset);
    } catch (error) {
      setPromoLogoError(
        error instanceof LogoError
          ? error.message
          : "No pudimos procesar esta imagen. Probá con otro archivo."
      );
    } finally {
      setIsProcessingLogo(false);
    }
  }

  function removePromoLogo() {
    setPromoLogo(null);
    setPromoLogoError("");
    if (promoImageDataUrl) void handleGeneratePromoImage(promoLanguage, null);
  }

  // El segundo destino se recuerda en este navegador (no se guarda en Supabase).
  function changeSecondUrl(value: string) {
    setPromoUrl2(value);
    setPromoImageDataUrl("");
    try {
      if (selectedBusiness) {
        const key = `resenatap-second-url-${selectedBusiness.id}`;
        if (value.trim()) window.localStorage.setItem(key, value);
        else window.localStorage.removeItem(key);
      }
    } catch {
      // Sin almacenamiento local: el valor igual se usa mientras la página esté abierta.
    }
  }

  function changePromoLanguage(language: PromoLanguage) {
    setPromoLanguage(language);
    // Si ya hay una imagen generada, se regenera en el idioma elegido.
    if (promoImageDataUrl) {
      void handleGeneratePromoImage(language);
    }
  }

  function handleDownloadPromoImage() {
    if (!promoImageDataUrl || !selectedBusiness) return;
    const link = document.createElement("a");
    link.href = promoImageDataUrl;
    link.download = `resenatap-${selectedBusiness.id}-${promoLanguage}.png`;
    document.body.appendChild(link);
    link.click();
    link.remove();
  }

  function handlePrintPromoImage() {
    if (!promoImageDataUrl || !selectedBusiness) return;
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      setPromoError("El navegador bloqueó la ventana de impresión. Permití las ventanas emergentes e intentá nuevamente.");
      return;
    }

    const safeName = selectedBusiness.name.replace(/[<>&"']/g, "");
    printWindow.document.open();
    printWindow.document.write(`<!doctype html>
      <html lang="es">
        <head>
          <meta charset="utf-8" />
          <meta name="viewport" content="width=device-width, initial-scale=1" />
          <title>Imprimir ReseñaTap - ${safeName}</title>
          <style>
            @page { size: A4 portrait; margin: 10mm; }
            * { box-sizing: border-box; }
            html, body { margin: 0; padding: 0; background: #fff; }
            body { display: flex; align-items: center; justify-content: center; min-height: 100vh; }
            img { display: block; width: auto; height: auto; max-width: 100%; max-height: 275mm; object-fit: contain; }
            @media screen { body { padding: 16px; } img { max-height: calc(100vh - 32px); } }
          </style>
        </head>
        <body>
          <img src="${promoImageDataUrl}" alt="Imagen promocional de ${safeName}" onload="window.focus(); window.print();" />
        </body>
      </html>`);
    printWindow.document.close();
  }

